contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint minSum, uint am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (am)); require(am <= 1000000000000000000000000000000);
        require(am > 0, "collect amount must be positive");
        require(address(this).balance >= am, "test contract must have enough Ether");
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: am}(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        c.Collect(am); if (__ESBMC_reverted()) return;
        assert(address(c).balance == balBefore - am);
    }
}

