// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 minSum, uint256 am) internal {
        am = bound(am, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(am > 0);
        vm.assume(address(this).balance >= am);
        try c.SetMinSum(0) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: am}() {} catch { return; }
        uint balBefore = address(c).balance;
        try c.Collect(am) {} catch { return; }
        assertTrue(address(c).balance == balBefore - am);
    }

    function testFuzz_run(uint256 minSum, uint256 am) public {
        _run(minSum, am);
    }

    receive() external payable {}
}
